        _lang() {
            try {
                if (window.vcI18n && window.vcI18n._lang) return String(window.vcI18n._lang).slice(0, 2);
                const l = document.documentElement.getAttribute("lang");
                if (l) return String(l).slice(0, 2);
            } catch (e) { }
            return "en";
        }

        _fmtNum(v, dec) {
            const s = Number(v).toFixed(dec);
            return (this._lang() === "es") ? s.replace(".", ",") : s;
        }

        _fmtScore5(v) {
            // Scale of 5, one decimal. Spanish uses a comma decimal separator.
            return this._fmtNum(v, 1);
        }

        _fmtNaira(v) {
            // NGN millions with the naira symbol, written after the figure in Spanish.
            const lang = this._lang();
            const abs = Math.abs(Number(v));
            if (lang === `es`) return `${abs.toFixed(0)} M₦`;
            return `₦${abs.toFixed(0)}M`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            if (!window.__authleadLangBound) {
                window.__authleadLangBound = true;
                document.addEventListener("express:langchanged", function() {
                    try {
                        const st = window.mySimulation && window.mySimulation.state;
                        if (!st) return;
                        const done = (st.history || []).length;
                        self._updateBriefing({ currentPeriod: Math.max(1, done + 1) });
                        if (st.domainState) self._renderCoach(st.domainState);
                    } catch (e) { }
                });
            }

            uiManager.bind(`trustDisplay`, `domainState.trust`, (v) => {
                const card = document.querySelector(`.authlead-card-trust`);
                if (card) {
                    card.classList.toggle(`authlead-kpi-high`, Number(v) >= 3.8);
                    card.classList.toggle(`authlead-kpi-low`, Number(v) < 2.6);
                }
                return self._fmtScore5(v);
            });
            uiManager.bind(`engageDisplay`, `domainState.engage`, (v) => {
                const card = document.querySelector(`.authlead-card-engage`);
                if (card) {
                    card.classList.toggle(`authlead-kpi-high`, Number(v) >= 3.8);
                    card.classList.toggle(`authlead-kpi-low`, Number(v) < 2.8);
                }
                return self._fmtScore5(v);
            });
            uiManager.bind(`perfDisplay`, `domainState.perf`, (v) => Math.round(Number(v)));
            uiManager.bind(`retainDisplay`, `domainState.retain`, (v) => {
                const card = document.querySelector(`.authlead-card-retain`);
                if (card) {
                    card.classList.toggle(`authlead-kpi-high`, Number(v) >= 70);
                    card.classList.toggle(`authlead-kpi-low`, Number(v) < 40);
                }
                return Math.round(Number(v)) + `%`;
            });
            uiManager.bind(`integrityDisplay`, `domainState.integrity`, (v) => {
                const bar = document.querySelector(`.authlead-integrity-bar`);
                if (bar) bar.classList.toggle(`authlead-integrity-broken`, Number(v) < 40);
                return Math.round(Number(v)) + ` / 100`;
            });

            // Range readouts.
            const ranges = [
                [`selfawareInput`, `selfawareReadout`],
                [`discloseInput`, `discloseReadout`],
                [`signalInput`, `signalReadout`],
                [`kpiInput`, `kpiReadout`]
            ];
            ranges.forEach(([inId, outId]) => {
                const inEl = document.getElementById(inId);
                const outEl = document.getElementById(outId);
                if (inEl && outEl) {
                    outEl.textContent = inEl.value;
                    inEl.addEventListener(`input`, function() { outEl.textContent = inEl.value; });
                }
            });
        }

        getChartConfig() {
            return {
