        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.trustHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                authleadChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.trustHistory },
                        { data: ds.engageHistory },
                        { data: ds.perfHistory },
                        { data: ds.retainHistory }
                    ]
                }
            };
        }

        // Composite (0-100) written to domainState.performance.overallScore each period for the
        // reporting/grading layer. Formula copied VERBATIM from v1.0.0 getPerformanceSummary.
        _composite(ds) {
            const trust = ds.trust;
            const engage = ds.engage;
            const perf = Math.round(ds.perf);
            const retain = Math.round(ds.retain);
            const integrity = Math.round(ds.integrity);
            const composite = Math.round(
                (trust / 5) * 100 * 0.26 +
                (engage / 5) * 100 * 0.18 +
                perf * 0.16 +
                retain * 0.18 +
                integrity * 0.22
            );
            return Math.max(0, Math.min(100, composite));
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === "function")
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.overallScore === "number") ? s.overallScore
                : (typeof s.totalScore === "number" ? s.totalScore
                : (typeof s.composite === "number" ? s.composite : 0));
            const grade = s.performanceKey ? T(s.performanceKey) : (s.performanceLabel || "");
            const met = !!s.met;
            const badge = met
                ? "<span class=\"authlead-cm-badge authlead-cm-yes\">" + T("cm_met") + "</span>"
                : "<span class=\"authlead-cm-badge authlead-cm-no\">" + T("cm_notmet") + "</span>";
            let failBadge = "";
            if (s.coverUp) failBadge += " <span class=\"authlead-cm-badge authlead-cm-no\">" + T("cm_coverup") + "</span>";
            if (s.bonusOnly) failBadge += " <span class=\"authlead-cm-badge authlead-cm-no\">" + T("cm_bonus") + "</span>";
            if (s.normViolated) failBadge += " <span class=\"authlead-cm-badge authlead-cm-no\">" + T("cm_normbroken") + "</span>";
            const li = function(x) { return "<li>" + x + "</li>"; };
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const questions = Array.isArray(s.questions) ? s.questions : [];
            const fmt5 = this._fmtScore5.bind(this);
            const metric = function(v, k) { return "<div class=\"authlead-cm-metric\"><span class=\"authlead-cm-mv\">" + v + "</span><span class=\"authlead-cm-ml\">" + T(k) + "</span></div>"; };
            const metrics = metric(fmt5(s.trust || 0), "cm_m_trust") + metric(fmt5(s.engage || 0), "cm_m_engage")
                + metric(Math.round(s.perf || 0), "cm_m_perf") + metric(Math.round(s.retain || 0) + "%", "cm_m_retain")
                + metric(Math.round(s.integrity || 0), "cm_m_integrity");
            const subs = "<div class=\"authlead-cm-subs\">"
                + "<div><strong>" + Math.round(s.outcome || 0) + "/100</strong> " + T("cm_sub_outcome") + "</div>"
                + "<div><strong>" + Math.round(s.process || 0) + "/100</strong> " + T("cm_sub_process") + "</div>"
                + "</div>";
            return ""
                + "<div class=\"authlead-completion\">"
                +   "<div class=\"authlead-cm-head\">"
                +     "<div class=\"authlead-cm-score\">" + score + "<span class=\"authlead-cm-score-max\">/100</span></div>"
                +     "<div class=\"authlead-cm-grade\">" + grade + " " + badge + failBadge + "</div>"
                +   "</div>"
                +   "<div class=\"authlead-cm-metrics\">" + metrics + "</div>"
                +   subs
                +   "<div class=\"authlead-cm-insights-title\">" + T("cm_turning") + "</div>"
                +   "<p class=\"authlead-cm-turning\">" + (s.turningPoint || "") + "</p>"
                +   "<div class=\"authlead-cm-insights-title\">" + T("cm_debrief") + "</div>"
                +   "<ul class=\"authlead-cm-insights\">" + insights.map(li).join("") + "</ul>"
                +   "<div class=\"authlead-cm-insights-title\">" + T("cm_questions") + "</div>"
                +   "<ol class=\"authlead-cm-insights authlead-cm-questions\">" + questions.map(li).join("") + "</ol>"
                + "</div>";
        }

        // Text of the option a log entry stands for, in the current language.
        _optLabel(e) {
            const t = function(k) { return window.mySimulation.t(k); };
            if (typeof e.v === "number") return t(this.READOUT[e.l]) + " " + e.v + "%";
            const key = (this.OPTKEY[e.l] || {})[e.o];
            let text = key ? t(key) : String(e.o);
            const cut = text.indexOf(" — ");
            if (cut > 0) text = text.slice(0, cut);
            return text;
        }

        // KPI effects of a log entry, for example: Trust -0.3, Integrity -8.
        _effects(e) {
            const t = function(k) { return window.mySimulation.t(k); };
            const names = ["cm_m_trust", "cm_m_engage", "cm_m_perf", "cm_m_retain", "cm_m_integrity"];
            const parts = [];
            for (let i = 0; i < 5; i++) {
                const v = e.e[i];
                if (!v) continue;
                const dec = (i < 2) ? 2 : 0;
                if (Number(Math.abs(v).toFixed(dec)) === 0) continue;
                parts.push(t(names[i]) + " " + (v > 0 ? "+" : "−") + this._fmtNum(Math.abs(v), dec));
            }
            return parts.join(", ");
        }

        _fill(key, e) {
            return window.mySimulation.t(key)
                .replace("{r}", String(e.r))
                .replace("{o}", this._optLabel(e))
                .replace("{x}", this._fmtNum(Math.abs(e.c), 1))
                .replace("{e}", this._effects(e));
        }

        // The debrief is built from what this run did: the costliest decision, the next two, the strongest move,
        // and the two effects that cross rounds (the round 2 norm tested in round 4; round 3 money read in round 4).
        _debrief(ds) {
            const t = function(k) { return window.mySimulation.t(k); };
            const log = (ds.log || []).slice();
            const levers = log.filter(function(e) { return e.l !== "echo"; });
            const costly = levers.filter(function(e) { return e.c <= -0.5; }).sort(function(a, b) { return a.c - b.c; });
            const gains = levers.filter(function(e) { return e.c >= 0.5; }).sort(function(a, b) { return b.c - a.c; });
            const self = this;
            let normNamed = false;
            const extra = function(e) {
                let k = (self.TPKEY[e.l] || {})[e.o];
                let s = k ? " " + t(k) : "";
                if (ds.normViolated && !normNamed && e.r === 4 && ((e.l === "confront" && e.o === "punish") || (e.l === "consistency" && e.o === "exception"))) {
                    s += " " + t("tp_x_normbroken");
                    normNamed = true;
                }
                return s;
            };
            const out = { turning: "", also: [], best: "", notes: [] };
            if (costly.length) {
                out.turning = this._fill("tp_frame", costly[0]) + extra(costly[0]);
                for (let i = 1; i < costly.length && i < 3; i++) out.also.push(this._fill("tp_also", costly[i]) + extra(costly[i]));
            } else {
                out.turning = t("tp_none");
            }
            if (gains.length) out.best = this._fill("tp_best", gains[0]);
            if (log.some(function(e) { return e.l === "echo"; })) out.notes.push(t("note_echo"));
            const played4 = log.some(function(e) { return e.r === 4; });
            if (ds.normViolated && !normNamed) out.notes.push(t("tp_x_normbroken"));
            else if (ds.cocreatedNorm && !ds.normViolated && played4) out.notes.push(t("note_norm_held"));
            return out;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const t = function(k) { return window.mySimulation.t(k); };
            const ds = window.mySimulation.state.domainState;
            const trust = ds.trust;
            const engage = ds.engage;
            const perf = Math.round(ds.perf);
            const retain = Math.round(ds.retain);
            const integrity = Math.round(ds.integrity);

            const composite = this._composite(ds);
            const sub = this._subscores(ds);

            const trusted = trust >= 3.8 && engage >= 3.6;
            const retained = retain >= 70;
            const consistent = integrity >= 65 && !ds.normViolated;
            const exposed = !!(ds.coverUp || ds.bonusOnly || ds.normViolated);

            // One rule gives the verdict. A run that carries a failure state is named for it;
            // every other run is banded by its score.
            let performanceKey = "grade_fractured";
            if (ds.coverUp) performanceKey = "grade_coverup";
            else if (ds.bonusOnly) performanceKey = "grade_bonustrap";
            else if (ds.normViolated) performanceKey = "grade_normbroken";
            else if (composite >= this.BAND_TURNAROUND) performanceKey = "grade_turnaround";
            else if (composite >= this.BAND_REBUILT) performanceKey = "grade_rebuilt";
            else if (composite >= this.BAND_MIXED) performanceKey = "grade_mixed";
            const met = (performanceKey === "grade_turnaround");

            const deb = this._debrief(ds);
            const insights = [];
            if (met) insights.push(t("insight_authentic"));
            else if (ds.coverUp) insights.push(t("insight_coverup"));
            else if (ds.bonusOnly) insights.push(t("insight_bonus"));
            else if (ds.normViolated) insights.push(t("insight_normbroken"));
            else insights.push(t("insight_short"));
            for (let i = 0; i < deb.also.length; i++) insights.push(deb.also[i]);
            if (deb.best) insights.push(deb.best);
            for (let i = 0; i < deb.notes.length; i++) insights.push(deb.notes[i]);
            if (trust < 3.0) insights.push(t("insight_lowtrust"));
            if (retain < 50) insights.push(t("insight_lowretain"));
            if (integrity >= 70 && !ds.normViolated) insights.push(t("insight_integrity"));
            if (perf < 45) insights.push(t("insight_lowperf"));

            return {
                trust: trust,
                engage: engage,
                perf: perf,
                retain: retain,
                integrity: integrity,
                trusted: trusted,
                retained: retained,
                consistent: consistent,
                exposed: exposed,
                composite: composite,
                score: composite,
                totalScore: composite,
                overallScore: composite,
                outcome: sub.outcome,
                process: sub.process,
                met: met,
                coverUp: ds.coverUp,
                bonusOnly: ds.bonusOnly,
                normViolated: ds.normViolated,
                performanceKey: performanceKey,
                performance: performanceKey,
                performanceLabel: t(performanceKey),
                turningPoint: deb.turning,
                insights: insights.slice(0, 5),
                questions: [t("cm_q1"), t("cm_q2"), t("cm_q3")]
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.coverUp) return window.mySimulation.t(`hint_coverup`);
            if (ds.normViolated) return window.mySimulation.t(`hint_normbroken`);
            if (ds.bonusOnly) return window.mySimulation.t(`hint_bonus`);
            if (ds.trust < 2.4 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_lowtrust`);
            if (ds.retain < 35 && state.currentPeriod >= 3) return window.mySimulation.t(`hint_lowretain`);
            if (ds.trust >= 3.6 && ds.retain >= 65 && ds.integrity >= 65) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.trust`, label: `Trust`, i18nKey: `col_trust`, formatter: (v) => self._fmtScore5(v) },
                { key: `results.engage`, label: `Engagement`, i18nKey: `col_engage`, formatter: (v) => self._fmtScore5(v) },
                { key: `results.perf`, label: `Performance`, i18nKey: `col_perf`, formatter: (v) => Math.round(v) },
                { key: `results.retain`, label: `Retention`, i18nKey: `col_retain`, formatter: (v) => Math.round(v) + `%` },
                { key: `results.integrity`, label: `Integrity`, i18nKey: `col_integrity`, formatter: (v) => Math.round(v) }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

        getTranslations() {
            return {
                en: {
                    title:                  `The Authentic Leader`,
                    subtitle:               `You inherit a fractured, low-trust 12-person squad on the morning your biggest client files a 90-day re-tender notice. Two key engineers have one foot out the door, and a junior just told you one of them is inflating ticket counts. Four decisions in fourteen days will show whether what you say in week one still matches what you do by its end.`,
